using Microsoft.AspNetCore.Mvc;using RaceDay.Mvc.Models;using RaceDay.Mvc.Services;
namespace RaceDay.Mvc.Controllers;
public class OrganiserController:Controller{readonly RaceDayApiClient api;public OrganiserController(RaceDayApiClient a)=>api=a;bool Role()=>HttpContext.Session.GetString("Role")=="Organiser";IActionResult Gate()=>HttpContext.Session.GetInt32("UserId")==null?RedirectToAction("Login","Account"):Forbid();
public async Task<IActionResult> Dashboard(){if(!Role())return Gate();var es=await api.Get<List<EventSummary>>("api/events?includePast=true")??new();var mine=es.Where(e=>e.OrganiserId==HttpContext.Session.GetInt32("UserId")).ToList();ViewBag.Enrolments=mine.Sum(e=>e.EnrolmentCount);return View(mine);}
public async Task<IActionResult> Categories(int id){if(!Role())return Gate();ViewBag.EventId=id;ViewBag.EventName=(await api.Get<EventDetail>($"api/events/{id}"))?.Name??"Event";return View(await api.Get<List<Category>>($"api/events/{id}/categories")??new());}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>AddCategory(int id,CategoryVm vm){if(!Role())return Gate();var r=await api.Send<Category>(HttpMethod.Post,$"api/events/{id}/categories",vm);TempData[r.Ok?"Success":"Error"]=r.Ok?"Category added.":r.Message;return RedirectToAction(nameof(Categories),new{id});}
public async Task<IActionResult>Enrolments(int id){if(!Role())return Gate();ViewBag.EventId=id;ViewBag.EventName=(await api.Get<EventDetail>($"api/events/{id}"))?.Name??"Event";return View(await api.Get<List<Enrolment>>($"api/events/{id}/enrolments")??new());}
public async Task<IActionResult>Results(int id){if(!Role())return Gate();ViewBag.EventId=id;ViewBag.EventName=(await api.Get<EventDetail>($"api/events/{id}"))?.Name??"Event";return View(await api.Get<List<Enrolment>>($"api/events/{id}/enrolments")??new());}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>SaveResult(int id,int enrolmentId,string finishTime,int position){if(!Role())return Gate();if(!TimeSpan.TryParse(finishTime,out var t)||t<=TimeSpan.Zero){TempData["Error"]="Use a valid time such as 00:48:22.";return RedirectToAction(nameof(Results),new{id});}var r=await api.Send<Result>(HttpMethod.Post,"api/results",new{EnrolmentId=enrolmentId,FinishTime=t,Position=position});TempData[r.Ok?"Success":"Error"]=r.Ok?"Result published.":r.Message;return RedirectToAction(nameof(Results),new{id});}}